insert into public.curated_recipes
  (title,summary,category,source_name,source_url,suitable_for_elimination,servings,preparation_minutes,ingredients,instructions,attribution_note,phase_note,published)
values
('Groene kiwi-spinaziesmoothie','Frisse snelle smoothie met kiwi, spinazie en lactosevrije yoghurt.','ontbijt','Monash FODMAP','https://www.monashfodmap.com/recipe/monash-low-fodmap-recipe-index/',true,1,5,E'1 groene kiwi\n40 g babyspinazie\n150 g lactosevrije yoghurt\n100 ml ongezoete amandelmelk\n1 tl chiazaad\nIJsblokjes',E'1. Schil de kiwi.\n2. Mix alle ingrediënten glad.\n3. Drink direct en houd deze hoeveelheid als één portie aan.','Eigen Nederlandstalige uitwerking van de Green Smoothie uit de Monash-receptenindex.','Monash neemt dit recept op in de Step-1 bibliotheek. Gebruik één afgemeten portie.',true),
('Vegan chocolade-chiapudding','Romig ontbijt of dessert met chia, cacao en ahornsiroop.','ontbijt','Monash FODMAP','https://www.monashfodmap.com/recipe/monash-low-fodmap-recipe-index/',true,2,10,E'30 g chiazaad\n250 ml amandelmelk\n1½ el cacaopoeder\n1 el pure ahornsiroop\n½ tl vanille-extract\n80 g aardbeien',E'1. Klop melk, cacao, ahornsiroop en vanille glad.\n2. Roer het chiazaad erdoor en koel minimaal vier uur.\n3. Roer opnieuw en verdeel over twee kommetjes.\n4. Serveer met aardbei.','Eigen Nederlandstalige uitwerking van de Vegan Chocolate Chia Pudding uit de Monash-receptenindex.','Verdeel het recept in twee porties en voeg geen extra gedroogd fruit of zoetstoffen toe.',true),
('Zoete-aardappel-fetafrittata','Ovenfrittata met spinazie, feta en een gecontroleerde portie zoete aardappel.','ontbijt','Monash FODMAP','https://www.monashfodmap.com/recipe/monash-low-fodmap-recipe-index/',true,4,40,E'300 g zoete aardappel, kleine blokjes\n8 eieren\n100 g feta\n80 g babyspinazie\nGroene toppen van 2 lente-uien\n1 el olijfolie\nPeper en zout',E'1. Verwarm de oven voor op 190 °C.\n2. Bak de aardappelblokjes in olie bijna gaar.\n3. Voeg spinazie en groene lente-ui toe.\n4. Giet losgeklopte eieren erover, verkruimel feta erop en bak 20–25 minuten.\n5. Snijd in vier gelijke stukken.','Eigen Nederlandstalige uitwerking van de Sweet Potato and Feta Frittata uit de Monash-receptenindex.','De hoeveelheid zoete aardappel is portiegevoelig; verdeel de frittata in vier stukken.',true),
('Maple granola met yoghurt','Knapperige havergranola met zaden, walnoot en lactosevrije yoghurt.','ontbijt','Monash FODMAP','https://www.monashfodmap.com/recipe/monash-low-fodmap-recipe-index/',true,6,30,E'240 g havermout\n40 g pompoenpitten\n30 g walnoten, gehakt\n2 el chiazaad\n3 el pure ahornsiroop\n2 el neutrale olie\n1 tl kaneel\nLactosevrije yoghurt bij het serveren',E'1. Verwarm de oven voor op 170 °C.\n2. Meng haver, pitten, noten en kaneel. Roer olie en siroop erdoor.\n3. Bak 20 minuten en schep halverwege om.\n4. Laat volledig afkoelen en verdeel in zes porties.','Eigen Nederlandstalige uitwerking van Maple Granola uit de Monash-receptenindex.','Houd één zesde van de granola per eetmoment aan en kies lactosevrije yoghurt.',true),
('Quinoabowl met geroosterde groente en ei','Vullende lunch met quinoa, zoete aardappel, spinazie en gebakken ei.','lunch','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,2,35,E'120 g quinoa\n150 g zoete aardappel, in blokjes\n1 rode paprika\n60 g babyspinazie\n2 eieren\n1 el knoflook-geïnfuseerde olie\n1 el citroensap\nPeper en zout',E'1. Kook de quinoa.\n2. Rooster aardappel en paprika 25 minuten op 200 °C met de olie.\n3. Bak de eieren.\n4. Verdeel quinoa, groenten en spinazie over twee kommen en leg het ei erop.\n5. Besprenkel met citroen.','Eigen Nederlandstalige uitwerking van de geroosterde zoete-aardappel-quinoabowl uit het Monash 7-daagse maaltijdplan.','Verdeel de zoete aardappel over twee porties om FODMAP-stapeling te beperken.',true),
('Aziatische quinoasalade','Koude quinoasalade met wortel, komkommer, paksoi en sesamdressing.','lunch','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,25,E'200 g quinoa\n1 wortel\n½ komkommer\n1 kleine paksoi\n80 g rodekool\n2 el sojasaus\n1 el sesamolie\n1 el rijstazijn\n1 tl geraspte gember\n1 el sesamzaad',E'1. Kook de quinoa en laat afkoelen.\n2. Snijd alle groenten fijn.\n3. Meng sojasaus, olie, azijn en gember.\n4. Schep alles samen en verdeel in vier porties.','Eigen Nederlandstalige uitwerking van de Asian Inspired Quinoa Salad uit het Monash-maaltijdplan.','Gebruik een sojasaus zonder ui of knoflook en houd de aangegeven verdeling aan.',true),
('Zalm-ricottafrittata','Eiwitrijke lunch met zalm, spinazie en lactosearme kaas.','lunch','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,35,E'8 eieren\n200 g gare zalm\n100 g ricotta\n80 g babyspinazie\nGroene toppen van 2 lente-uien\n1 el olijfolie\nDille, peper en zout',E'1. Verwarm de oven voor op 185 °C.\n2. Laat spinazie in olie slinken.\n3. Klop de eieren los met dille en kruiden.\n4. Verdeel zalm, ricotta en lente-ui in de pan, giet ei erover en bak 20 minuten in de oven.\n5. Deel in vieren.','Eigen Nederlandstalige uitwerking van de Salmon & Ricotta Frittata uit het Monash-maaltijdplan.','Controleer je persoonlijke tolerantie voor ricotta en houd één kwart als portie aan.',true),
('Kruidige wortelfritters','Krokante groentekoekjes voor lunch met ei of groene salade.','lunch','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,25,E'400 g geraspte wortel\n3 eieren\n60 g rijstmeel\nGroene toppen van 2 lente-uien\n1 tl komijn\n½ tl korianderpoeder\n2 el olie\nPeper en zout',E'1. Knijp overtollig vocht uit de wortel.\n2. Meng met ei, rijstmeel, groene lente-ui en kruiden.\n3. Vorm acht kleine koekjes.\n4. Bak ze aan beide kanten goudbruin en serveer twee per portie.','Eigen Nederlandstalige uitwerking van de Carrot Fritters uit het Monash-maaltijdplan.','Twee kleine fritters vormen één van de vier porties.',true),
('Aziatische kip-noedelsalade','Lichte maaltijdsalade met rijstnoedels, kip en knapperige groenten.','avondeten','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,30,E'400 g kipfilet\n240 g rijstnoedels\n1 wortel\n½ komkommer\n1 rode paprika\n100 g paksoi\n2 el sojasaus\n2 el limoensap\n1 el sesamolie\n1 tl gember\nKoriander, optioneel',E'1. Bereid de noedels en spoel koud.\n2. Bak de kip gaar en snijd in repen.\n3. Snijd de groenten fijn.\n4. Meng sojasaus, limoen, olie en gember en schep alles samen.\n5. Verdeel in vier kommen.','Eigen Nederlandstalige uitwerking van de Asian Chicken Noodle Salad uit het Monash 7-daagse maaltijdplan.','Controleer noedels en sojasaus op extra ui of knoflook.',true),
('Milde kip-madras met rijst','Geurige curry zonder ui of knoflook, met tomaat, wortel en spinazie.','avondeten','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,45,E'500 g kipdijfilet\n250 g basmatirijst\n400 g tomatenblokjes uit blik\n2 wortelen\n100 g babyspinazie\n2 el knoflook-geïnfuseerde olie\n2 el madras-kruiden zonder ui of knoflook\n200 ml lactosevrije yoghurt\nGroene lente-ui, zout',E'1. Kook de rijst.\n2. Bak kip en wortel in geïnfuseerde olie.\n3. Voeg kruiden en tomaat toe en stoof 20 minuten.\n4. Roer spinazie en yoghurt er op laag vuur door.\n5. Verdeel curry en rijst in vier porties.','Eigen Nederlandstalige uitwerking van Chicken Madras Curry uit het Monash-maaltijdplan.','Gebruik uitsluitend een kruidenmix zonder ui- of knoflookpoeder.',true),
('Romige pompoen-saliegnocchi','Vegetarische gnocchi met kabocha-pompoen en knapperige salie.','avondeten','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,35,E'500 g glutenvrije aardappelgnocchi\n400 g kabocha-pompoen\n200 ml lactosevrije kookroom\n12 salieblaadjes\n2 el knoflook-geïnfuseerde olie\n40 g Parmezaan\nPeper en zout',E'1. Rooster pompoenblokjes 25 minuten op 200 °C.\n2. Kook de gnocchi volgens de verpakking.\n3. Bak salie krokant in olie en neem uit de pan.\n4. Pureer de helft van de pompoen met room, verwarm en schep gnocchi en overige pompoen erdoor.\n5. Verdeel in vieren en werk af met salie en kaas.','Eigen Nederlandstalige uitwerking van Creamy Pumpkin & Sage Gnocchi uit het Monash-maaltijdplan.','Kies gnocchi zonder tarwe, inuline, ui of knoflook en verdeel in vier porties.',true),
('Zalm met dikke aardappelparten','Eenvoudige ovenmaaltijd met zalm, aardappel en sperziebonen.','avondeten','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,45,E'4 zalmfilets van ca. 150 g\n800 g aardappelen\n300 g sperziebonen\n2 el olijfolie\n1 citroen\n1 tl paprikapoeder\nDille, peper en zout',E'1. Verwarm de oven voor op 210 °C.\n2. Snijd aardappelen in dikke parten, meng met olie en kruiden en rooster 25 minuten.\n3. Voeg zalm toe en bak nog 12–15 minuten.\n4. Kook of stoom de bonen.\n5. Serveer met citroen en dille.','Eigen Nederlandstalige uitwerking van Atlantic Salmon with Thick Cut Potato Chips uit het Monash-maaltijdplan.','Ongekruide zalm en aardappel zijn van nature low-FODMAP; controleer toegevoegde sauzen.',true),
('Thaise groene kipcurry','Frisse curry met kip, paksoi, paprika en kokosmelk.','avondeten','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,4,35,E'500 g kipfilet\n250 g jasmijnrijst\n400 ml kokosmelk\n1 rode paprika\n2 kleine paksoi\n100 g sperziebonen\n2 el groene currypasta zonder ui of knoflook\n1 el knoflook-geïnfuseerde olie\n1 limoen\nBasilicum',E'1. Kook de rijst.\n2. Bak kip in de geïnfuseerde olie.\n3. Voeg currypasta, kokosmelk en groenten toe en laat 15 minuten zacht koken.\n4. Breng op smaak met limoen en basilicum.\n5. Verdeel in vier porties.','Eigen Nederlandstalige uitwerking van Thai Green Chicken Curry uit de Monash meal-prepselectie.','Currypasta en kokosmelk zijn merk- en portiegevoelig; controleer het etiket en houd vier porties aan.',true),
('Pompoen-wortelsoep','Zachte meal-prepsoep met kabocha, wortel, gember en lactosevrije room.','lunch','Monash FODMAP','https://www.monashfodmap.com/blog/planning-low-fodmap-meals/',true,6,40,E'700 g kabocha-pompoen\n400 g wortel\nGroene delen van 1 prei\n1 el geraspte gember\n1,2 l bouillon zonder ui of knoflook\n150 ml lactosevrije room\n2 el olijfolie\nPeper en zout',E'1. Bak groen preiblad en gember kort in olie.\n2. Voeg pompoen, wortel en bouillon toe.\n3. Kook 25 minuten en pureer glad.\n4. Roer room erdoor en verdeel in zes kommen.','Eigen Nederlandstalige uitwerking van Roasted Pumpkin & Carrot Soup uit de Monash meal-prepselectie.','Gebruik kabocha-pompoen en gecertificeerde of zelfgemaakte bouillon zonder ui en knoflook.',true),
('Rode-paprikahummus','Romige dip op basis van uitgelekte kikkererwten en geroosterde paprika.','tussendoor','Michigan Medicine','https://www.michiganmedicine.org/health-lab/5-easy-low-fodmap-diet-recipes-every-meal',true,6,15,E'240 g kikkererwten uit blik, zeer goed afgespoeld\n1 geroosterde rode paprika\n2 el tahin\n2 el citroensap\n1 el knoflook-geïnfuseerde olie\n½ tl komijn\nWater, peper en zout',E'1. Spoel de kikkererwten zorgvuldig af.\n2. Mix alle ingrediënten glad en voeg beetje voor beetje water toe.\n3. Verdeel in zes kleine porties en serveer met wortel of komkommer.','Eigen Nederlandstalige uitwerking van Roasted Red Pepper Hummus, aanbevolen door Michigan Medicine.','Kikkererwten zijn portiegevoelig; eet maximaal één zesde van deze hoeveelheid per keer.',true),
('Snelle chocolade-mugcake','Eenpersoons chocoladetaartje uit de magnetron.','tussendoor','Monash FODMAP','https://www.monashfodmap.com/recipe/?submit_button=Search',true,1,5,E'30 g rijstmeel\n1 el cacaopoeder\n1½ el suiker\n¼ tl bakpoeder\n45 ml lactosevrije melk\n1 el neutrale olie\n1 el pure chocoladestukjes',E'1. Meng meel, cacao, suiker en bakpoeder in een ruime mok.\n2. Roer melk en olie erdoor tot het beslag glad is.\n3. Voeg chocolade toe.\n4. Verwarm 60–90 seconden in de magnetron en laat kort afkoelen.','Eigen Nederlandstalige uitwerking van Chocolate Mug Cake uit de Monash-receptencollectie.','Eet de mugcake als één portie en kies chocolade zonder melkbestanddelen met lactose als je daarvoor gevoelig bent.',true)
